mapper.update:
update workflow_node_run
set tool_call_count = tool_call_count + #{delta},
    updated_at = now()
where 1 = 1
  and run_id = #{runId}
  and node_key = #{nodeKey}

update workflow_node_run
set tool_denied_count = tool_denied_count + #{delta},
    updated_at = now()
where 1 = 1
  and run_id = #{runId}
  and node_key = #{nodeKey}
